codeExample:
div {
  width: 200px;
  padding: 10px;
  border: 2px solid black;
  margin: 20px;
}

.relative {
  position: relative;
  top: 10px;
}
.absolute {
  position: absolute;
  top: 50px;
  left: 50px;
}
.fixed {
  position: fixed;
  top: 0;
}

a:hover {
  color: red;
}
input:focus {
  border: 2px solid blue;
}

html {
  font-size: 16px;
}
div {
  font-size: 1.5em; /* 1.5 times the parent font size */
}
p {
  font-size: 1rem; /* 16px, relative to root */
}
